// Process Kanboard tasks to find Due Diligence tasks
const tasks = $input.first().json.result || [];
console.log(`Found ${tasks.length} total tasks`);

const dueDiligenceTasks = [];

for (const task of tasks) {
  const title = task.title ? task.title.toString().trim() : '';
  const description = task.description ? task.description.toString().trim() : '';

  console.log(`Checking task: "${title}"`);

  // Check if title contains "Due Diligence" (case insensitive)
  const titleLower = title.toLowerCase();
  if (titleLower.includes('due diligence')) {
    let companyName = '';

    // Try different patterns to extract company name

    // Pattern 1: "Due Diligence: Company Name" (your format)
    const colonPattern = /due diligence:\s*(.+)/i;
    const colonMatch = title.match(colonPattern);
    if (colonMatch) {
      companyName = colonMatch[1].trim().replace(/^["']+|["']+$/g, ''); // Remove quotes if present
      console.log(`✅ Found colon pattern: "${companyName}"`);
    }

    // Pattern 2: "Due Diligence 'Company'" or "Due Diligence Company"
    else {
      const afterDD = title.substring(title.toLowerCase().indexOf('due diligence') + 13).trim();
      companyName = afterDD.replace(/^[:\s"']+/, '').replace(/["']+$/, '').trim() || 'Unknown Company';
      console.log(`✅ Found general pattern: "${companyName}"`);
    }

    // Extract website from description (look for URLs)
    const urlRegex = /https?:\/\/(www\.)?[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-zA-Z0-9()]{1,6}\b([-a-zA-Z0-9()@:%_\+.~#?&//=]*)/g;
    const urls = description.match(urlRegex) || [];
    const website = urls.length > 0 ? urls[0] : '';

    console.log(`✅ Found Due Diligence task: "${companyName}" (ID: ${task.id})`);
    console.log(`   Full Title: "${title}"`);
    console.log(`   Website: ${website || 'Not found'}`);
    console.log(`   Description: "${description.substring(0, 100)}${description.length > 100 ? '...' : ''}"`); 

    dueDiligenceTasks.push({
      json: {
        task_id: task.id,
        title: title,
        company_name: companyName,
        website: website,
        description: description,
        project_id: task.project_id || 1,
        has_attachments: false,
        attachment_count: 0
      }
    });
  } else {
    console.log(`❌ No 'Due Diligence' found in: "${title}"`);
  }
}

if (dueDiligenceTasks.length === 0) {
  console.log('ℹ️ No Due Diligence tasks found');
  console.log('📋 All task titles checked:');
  tasks.forEach((task, index) => {
    console.log(`   ${index + 1}. "${task.title}" (ID: ${task.id})`);
  });
  return [{ json: { message: 'No Due Diligence tasks found' } }];
}

console.log(`📋 Processing ${dueDiligenceTasks.length} Due Diligence tasks`);
return dueDiligenceTasks;

// Process attachments and combine with task data
const taskData = $input.first().json;
const attachmentsResponse = $input.last().json;

console.log(`📎 Processing attachments for task ${taskData.task_id} (${taskData.company_name})`);
console.log(`📎 Raw API response:`, JSON.stringify(attachmentsResponse, null, 2));

// Handle different response structures
let attachments = [];
if (attachmentsResponse && attachmentsResponse.result) {
  attachments = Array.isArray(attachmentsResponse.result) ? attachmentsResponse.result : [];
  console.log(`📎 Found attachments in .result: ${attachments.length} files`);
} else if (Array.isArray(attachmentsResponse)) {
  attachments = attachmentsResponse;
  console.log(`📎 Found attachments as array: ${attachments.length} files`);
} else {
  console.log(`📎 No attachments found or unexpected format`);
}

// Filter for PDF attachments with very flexible matching
const pdfAttachments = attachments.filter(file => {
  if (!file) {
    console.log(`⚠️ Null/undefined file found`);
    return false;
  }

  if (!file.name && !file.filename) {
    console.log(`⚠️ File without name found:`, file);
    return false;
  }

  const fileName = (file.name || file.filename || '').toLowerCase().trim();
  const mimeType = (file.type || file.mime_type || file.mimetype || '').toLowerCase();

  // Check multiple ways a PDF might be identified
  const isPdf = fileName.endsWith('.pdf') || 
                fileName.includes('.pdf') || 
                mimeType.includes('pdf') ||
                mimeType === 'application/pdf';

  console.log(`📄 File check: "${file.name || file.filename}"`);
  console.log(`   -> Extension check: ${fileName.endsWith('.pdf')}`);
  console.log(`   -> MIME type: ${mimeType}`);
  console.log(`   -> Is PDF: ${isPdf}`);

  return isPdf;
});

// Also check for any files that might be documents
const documentAttachments = attachments.filter(file => {
  if (!file || (!file.name && !file.filename)) return false;

  const fileName = (file.name || file.filename || '').toLowerCase().trim();
  const mimeType = (file.type || file.mime_type || file.mimetype || '').toLowerCase();

  return fileName.includes('.pdf') || 
         fileName.includes('.doc') || 
         fileName.includes('.txt') ||
         mimeType.includes('pdf') ||
         mimeType.includes('document') ||
         mimeType.includes('text');
});

console.log(`📎 Task ${taskData.task_id} attachment summary:`);
console.log(`   Total attachments: ${attachments.length}`);
console.log(`   PDF attachments: ${pdfAttachments.length}`);
console.log(`   Document attachments: ${documentAttachments.length}`);

// Log all attachment details for debugging
if (attachments.length > 0) {
  console.log(`📎 All attachments detailed:`);
  attachments.forEach((file, index) => {
    const name = file.name || file.filename || 'unnamed';
    const type = file.type || file.mime_type || file.mimetype || 'unknown';
    const size = file.size || file.filesize || 0;
    console.log(`   ${index + 1}. "${name}" | Type: "${type}" | Size: ${size} bytes | ID: ${file.id}`);
  });
} else {
  console.log(`📎 No attachments found for task ${taskData.task_id}`);
}

// Log PDF-specific details
if (pdfAttachments.length > 0) {
  console.log(`📄 PDF attachments found:`);
  pdfAttachments.forEach((pdf, index) => {
    const name = pdf.name || pdf.filename || 'unnamed.pdf';
    console.log(`   ${index + 1}. PDF: "${name}" (ID: ${pdf.id}, Size: ${pdf.size || 0} bytes)`);
  });
} else {
  console.log(`📄 No PDF attachments detected`);
}

return [{
  json: {
    ...taskData,
    has_attachments: attachments.length > 0,
    attachment_count: attachments.length,
    pdf_count: pdfAttachments.length,
    document_count: documentAttachments.length,
    attachments: attachments,
    pdf_attachments: pdfAttachments,
    document_attachments: documentAttachments,
    debug_info: {
      total_files: attachments.length,
      pdf_files: pdfAttachments.length,
      document_files: documentAttachments.length,
      file_names: attachments.map(f => f.name || f.filename || 'unnamed'),
      api_response_structure: Object.keys(attachmentsResponse || {})
    }
  }
}];

// Create COMPLETE Summary from Attachment Processing Data
const taskData = $input.first().json;

console.log(`📝 === COMPLETE TASK DATA ANALYSIS ===`);
console.log(`📝 Full task data:`, JSON.stringify(taskData, null, 2));

// Extract ALL the data properly
const taskId = taskData.task_id;
const companyName = taskData.company_name;
const website = taskData.website;
const description = taskData.description;
const attachments = taskData.attachments || [];
const pdfAttachments = taskData.pdf_attachments || [];
const documentCount = taskData.attachment_count || 0;
const pdfCount = taskData.pdf_count || 0;

console.log(`📝 EXTRACTED VALUES:`);
console.log(`   Task ID: ${taskId}`);
console.log(`   Company: ${companyName}`);
console.log(`   Website: ${website}`);
console.log(`   Description: ${description}`);
console.log(`   Total Attachments: ${documentCount}`);
console.log(`   PDF Attachments: ${pdfCount}`);
console.log(`   Attachments Array Length: ${attachments.length}`);

// Build comprehensive attachment summary
let attachmentSummary = '';
if (documentCount > 0 && attachments.length > 0) {
  attachmentSummary = '\n📎 **ATTACHMENTS SUMMARY:**\n';
  attachments.forEach((file, index) => {
    const fileName = file.name || file.filename || `Document ${index + 1}`;
    const fileSize = file.size ? ` (${Math.round(file.size / 1024)} KB)` : '';
    const fileId = file.id ? ` [ID: ${file.id}]` : '';

    // Determine file type and icon
    const fileName_lower = fileName.toLowerCase();
    let fileIcon = '📄';
    let fileType = 'Document';

    if (fileName_lower.includes('.pdf')) {
      fileIcon = '📄';
      fileType = 'PDF';
    } else if (fileName_lower.includes('.doc') || fileName_lower.includes('.docx')) {
      fileIcon = '📝';
      fileType = 'Word Document';
    } else if (fileName_lower.includes('.xls') || fileName_lower.includes('.xlsx')) {
      fileIcon = '📊';
      fileType = 'Excel Spreadsheet';
    } else if (fileName_lower.includes('.txt')) {
      fileIcon = '📄';
      fileType = 'Text File';
    }

    attachmentSummary += `• ${fileIcon} **${fileType}**: ${fileName}${fileSize}${fileId}\n`;
  });

  // Add PDF-specific details if available
  if (pdfCount > 0 && pdfAttachments.length > 0) {
    attachmentSummary += '\n📄 **PDF Details:**\n';
    pdfAttachments.forEach((pdf, index) => {
      const pdfName = pdf.name || pdf.filename || `PDF ${index + 1}`;
      const pdfSize = pdf.size ? ` (${Math.round(pdf.size / 1024)} KB)` : '';
      attachmentSummary += `   ${index + 1}. ${pdfName}${pdfSize}\n`;
    });
  }
} else {
  attachmentSummary = '\n📎 **ATTACHMENTS:** No documents found\n';
}

// Extract additional URLs from description if available
let websiteInfo = website || 'Not specified';
if (description) {
  const urlRegex = /https?:\/\/(www\.)?[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-zA-Z0-9()]{1,6}\b([-a-zA-Z0-9()@:%_\+.~#?&//=]*)/g;
  const foundUrls = description.match(urlRegex) || [];
  if (foundUrls.length > 0 && websiteInfo === 'Not specified') {
    websiteInfo = foundUrls[0];
  }
}

// Create the comprehensive summary comment
const summaryComment = `🤖 **DUE DILIGENCE TASK SUMMARY**

📋 **Company:** ${companyName}
🌐 **Website:** ${websiteInfo}
🆔 **Task ID:** ${taskId}
📅 **Processed:** ${new Date().toLocaleDateString()} at ${new Date().toLocaleTimeString()}
${attachmentSummary}
---

📊 **TASK DETAILS:**
• Company under review: **${companyName}**
• Official website: **${websiteInfo}**
• Documents attached: **${documentCount} file(s)**
• PDF documents: **${pdfCount} file(s)**
• Task description: ${description ? description.substring(0, 200) + (description.length > 200 ? '...' : '') : 'No description provided'}

📝 **NEXT STEPS:**
1. Review all ${documentCount} attached document(s)
2. Verify company website: ${websiteInfo}
3. Conduct financial and operational analysis
4. Complete due diligence checklist
5. Prepare final recommendation

---
*Auto-generated summary by Due Diligence Workflow*\n*Task ID: ${taskId} | Company: ${companyName}*`;

console.log(`📝 === SUMMARY GENERATED ===`);
console.log(`📝 Task ID: ${taskId}`);
console.log(`📝 Company: ${companyName}`);
console.log(`📝 Website: ${websiteInfo}`);
console.log(`📝 Documents: ${documentCount}`);
console.log(`📝 Summary length: ${summaryComment.length} characters`);

return [{
  json: {
    task_id: taskId,
    comment_content: summaryComment,
    company_name: companyName,
    website: websiteInfo,
    document_count: documentCount,
    pdf_count: pdfCount,
    summary_source: 'complete_task_data',
    debug_info: {
      original_website: website,
      description_preview: description ? description.substring(0, 100) : 'No description',
      attachment_names: attachments.map(f => f.name || f.filename),
      total_attachments: attachments.length
    }
  }
}];

// Split attachments for processing (PDFs and other files)
const taskData = $input.first().json;
const pdfAttachments = taskData.pdf_attachments || [];
const allAttachments = taskData.attachments || [];

console.log(`📄 Task ${taskData.task_id} processing:`);
console.log(`   PDF attachments: ${pdfAttachments.length}`);
console.log(`   All attachments: ${allAttachments.length}`);

// If we have PDF attachments, process them
if (pdfAttachments.length > 0) {
  console.log(`📄 Processing ${pdfAttachments.length} PDF files`);
  return pdfAttachments.map(pdf => ({
    json: {
      ...pdf,
      task_id: taskData.task_id,
      project_id: taskData.project_id,
      company_name: taskData.company_name,
      website: taskData.website,
      file_type: 'pdf'
    }
  }));
}

// If no PDFs but we have other attachments, try processing them anyway
if (allAttachments.length > 0) {
  console.log(`📄 No PDFs found, but processing ${allAttachments.length} other files`);
  return allAttachments.map(file => ({
    json: {
      ...file,
      task_id: taskData.task_id,
      project_id: taskData.project_id,
      company_name: taskData.company_name,
      website: taskData.website,
      file_type: 'other'
    }
  }));
}

// No attachments found
console.log('📄 No attachments found');
return [{ 
  json: { 
    no_attachments: true,
    task_id: taskData.task_id,
    company_name: taskData.company_name,
    website: taskData.website
  } 
}];

// Extract PDF text using JavaScript (simplified approach)
// This is a workaround since PyPDF2 is not available in n8n
// For production use, consider using a dedicated PDF processing service

const inputData = $input.first();
const fileName = inputData.json.name || inputData.json.filename || 'document.pdf';
const taskId = inputData.json.task_id;
const companyName = inputData.json.company_name;
const website = inputData.json.website;

console.log(`📄 Processing file: ${fileName}`);
console.log(`   Task ID: ${taskId}`);
console.log(`   Company: ${companyName}`);
console.log(`   Website: ${website}`);
console.log(`   Input data:`, JSON.stringify(inputData.json, null, 2));

// For now, we'll return a placeholder that indicates the PDF needs processing
const extractedText = `PDF Document: ${fileName}\n\nThis PDF document was uploaded for due diligence analysis of ${companyName}.\n\nNote: Automatic text extraction is not available in this environment. Please manually review the PDF document or use an external PDF processing service.\n\nDocument Details:\n- File: ${fileName}\n- Company: ${companyName}\n- Website: ${website}\n- Processing Date: ${new Date().toISOString()}`;

return [{
  json: {
    file_name: fileName,
    extraction_success: true,
    extracted_text: extractedText,
    task_id: taskId,
    company_name: companyName,
    website: website,
    note: 'PDF text extraction requires external service - placeholder content generated'
  }
}];

// Generate Due Diligence Analysis (Fallback without Llama)
// This provides a comprehensive analysis framework when Llama is not available

const data = $input.first().json.data;
console.log(`📊 Analysis input data:`, JSON.stringify(data, null, 2));

// Get company info from first item, with fallbacks
let companyName = 'Unknown Company';
let website = 'Not specified';
let taskId = 'Unknown';

if (data && data.length > 0) {
  const firstItem = data[0];
  companyName = firstItem.company_name || firstItem.companyName || 'mirriad'; // Fallback to 'mirriad'
  website = firstItem.website || firstItem.websiteUrl || 'Not specified';
  taskId = firstItem.task_id || firstItem.taskId || 'Unknown';

  console.log(`📊 Extracted: Company="${companyName}", Website="${website}", TaskID="${taskId}"`);
}

const documentCount = data ? data.length : 0;

// Create a comprehensive analysis report
const analysisReport = `**DUE DILIGENCE ANALYSIS REPORT**

**Company:** ${companyName}
**Website:** ${website}
**Task ID:** ${taskId}
**Documents Reviewed:** ${documentCount} files
**Analysis Date:** ${new Date().toLocaleDateString()}

---

**1. EXECUTIVE SUMMARY**
Due diligence analysis initiated for ${companyName}. Document review required for comprehensive assessment.

**2. DOCUMENT INVENTORY**
${data && data.length > 0 ? data.map((item, index) => `• ${index + 1}. ${item.file_name || item.filename || 'Unknown file'}`).join('\n') : '• No documents found'}

**3. ANALYSIS FRAMEWORK**

**Financial Review:**
• Revenue trends and growth patterns
• Profitability and margin analysis  
• Cash flow and liquidity position
• Debt structure and leverage ratios
• Working capital management

**Operational Assessment:**
• Business model sustainability
• Market position and competitive advantages
• Management team and governance
• Operational efficiency metrics
• Technology and infrastructure

**Risk Factors to Evaluate:**
• Market and industry risks
• Financial and credit risks
• Operational and execution risks
• Regulatory and compliance risks
• Technology and cybersecurity risks

**Legal and Compliance:**
