---

**Note:** This analysis framework provides the structure for comprehensive due diligence. Manual review of the attached documents is required to complete the assessment.

**Action Required:** Please review the documents listed above and update this analysis with specific findings.`;

console.log(`📊 Generated analysis framework for ${companyName}`);
console.log(`📄 ${documentCount} documents require manual review`);

return [{
  json: {
    response: analysisReport,
    company_name: companyName,
    website: website,
    task_id: taskId,
    document_count: documentCount,
    analysis_type: 'framework_generated',
    requires_manual_review: true
  }
}];

// Create comprehensive summary for Kanboard comment - Direct from processed attachments
const analysisData = $input.first().json;
console.log(`📝 Full analysis input:`, JSON.stringify(analysisData, null, 2));

// Try to get data from multiple possible sources
let companyName = 'Unknown Company';
let website = 'Not specified';
let taskId = 'Unknown';
let attachments = [];
let documentCount = 0;

// First try the direct analysis data
if (analysisData.company_name) {
  companyName = analysisData.company_name;
  website = analysisData.website || 'Not specified';
  taskId = analysisData.task_id;
}

// Try to get attachment info from aggregated data
if (analysisData.data && Array.isArray(analysisData.data)) {
  const data = analysisData.data;
  documentCount = data.length;

  // Get company info from first item if not already set
  if (data.length > 0 && companyName === 'Unknown Company') {
    const firstItem = data[0];
    companyName = firstItem.company_name || firstItem.companyName || companyName;
    website = firstItem.website || firstItem.websiteUrl || website;
    taskId = firstItem.task_id || firstItem.taskId || taskId;
  }

  // Build attachments list
  attachments = data.map(item => ({
    name: item.file_name || item.filename || item.name || 'Unknown file',
    type: (item.file_name || item.filename || item.name || '').toLowerCase().includes('.pdf') ? 'PDF' : 'Document'
  }));
}

console.log(`📝 Summary data: Company="${companyName}", Website="${website}", Docs=${documentCount}`);
console.log(`📎 Attachments:`, attachments);

// Build attachment summary
let attachmentSummary = '';
if (documentCount > 0 && attachments.length > 0) {
  attachmentSummary = '\n📎 **ATTACHMENTS SUMMARY:**\n';
  attachments.forEach((file, index) => {
    const fileIcon = file.type === 'PDF' ? '📄' : '📄';
    attachmentSummary += `• ${fileIcon} ${file.type}: ${file.name}\n`;
  });
} else {
  attachmentSummary = '\n📎 **ATTACHMENTS:** No documents found\n';
}

// Create the comprehensive summary comment
const summaryComment = `🤖 **DUE DILIGENCE TASK SUMMARY**

📋 **Company:** ${companyName}
🌐 **Website:** ${website}
📅 **Processed:** ${new Date().toLocaleDateString()} at ${new Date().toLocaleTimeString()}
${attachmentSummary}
---

📊 **QUICK OVERVIEW:**
• Company under review: ${companyName}
• Official website: ${website === 'Not specified' ? 'Website not provided in task description' : website}
• Documents attached: ${documentCount} file(s)
• Status: Ready for detailed analysis

📝 **NEXT STEPS:**
1. Review all attached documents
2. Verify company website and gather additional information
3. Conduct financial and operational analysis
4. Complete due diligence checklist
5. Prepare final recommendation

---
*Auto-generated summary by Due Diligence Workflow*`;

return [{
  json: {
    task_id: taskId,
    comment_content: summaryComment,
    company_name: companyName,
    website: website,
    document_count: documentCount
  }
}];
